"""Distributed toroidal-current flux on a regular source grid."""
from __future__ import annotations

import numpy as np

from .greens import _weighted_psi


def get_deltapsi(data, Req, Zeq):
    """Interpolate the flux generated by a netCDF current-grid variable.

    ``curr_diamcurv_phi`` is read in A/cm² with trailing dimensions
    ``(nzeqadim, nreqadim)``.  An optional leading layer axis is summed.  The
    source grid spans the extrema of the requested target arrays and uses the
    local rectangular cell area for source weights.
    """
    target_r, target_z = np.asarray(Req, dtype=float), np.asarray(Zeq, dtype=float)
    if (target_r.ndim != 2 or target_z.shape != target_r.shape or target_r.size == 0
            or not np.all(np.isfinite(target_r)) or not np.all(np.isfinite(target_z))
            or np.any(target_r < 0.0) or np.ptp(target_r) <= 0.0 or np.ptp(target_z) <= 0.0):
        raise ValueError("finite equal 2-D targets with nonnegative R and positive R,Z spans required")
    try:
        nr = data.dimensions["nreqadim"].size
        nz = data.dimensions["nzeqadim"].size
        variable = data.variables["curr_diamcurv_phi"]
    except (KeyError, AttributeError) as exc:
        raise ValueError("current variable and named source-grid dimensions required") from exc
    if nr < 2 or nz < 2:
        raise ValueError("source grid needs at least two nodes in each direction")

    values = np.ma.asarray(variable[:], dtype=float)
    if (values.ndim not in (2, 3) or values.shape[-2:] != (nz, nr)
            or tuple(variable.dimensions[-2:]) != ("nzeqadim", "nreqadim")
            or np.any(np.ma.getmaskarray(values)) or not np.all(np.isfinite(values.data))):
        raise ValueError("finite unmasked current with trailing (nzeqadim,nreqadim) dimensions required")
    if getattr(variable, "units", "A/cm^2") != "A/cm^2":
        raise ValueError("current must be expressed in A/cm^2")

    current = np.array(values.data, dtype=float, copy=True)
    if current.ndim == 3:
        current = current.sum(axis=0)
    radial = np.linspace(target_r.min(), target_r.max(), nr)
    axial = np.linspace(target_z.min(), target_z.max(), nz)
    source_r, source_z = np.meshgrid(radial, axial)
    points = np.column_stack((source_r.ravel(), source_z.ravel()))
    with np.errstate(over="raise", invalid="raise"):
        cell_area = (radial[1] - radial[0]) * (axial[1] - axial[0])
        source_weights = current.ravel() * 1.0e4 * cell_area
        flux_nodes = _weighted_psi(np.column_stack((points, source_weights)), points, zero_self=True)

    if not np.all(np.isfinite(flux_nodes)):
        raise FloatingPointError("distributed flux is not finite")
    from scipy.interpolate import LinearNDInterpolator

    query = np.column_stack((target_r.ravel(), target_z.ravel()))
    interpolated = np.asarray(LinearNDInterpolator(points, flux_nodes)(query))
    # The interpolator is allowed to round away exact nodes. Restore nodes
    # within a construction-scale neighbourhood so the discrete self rule is
    # observable to callers.
    eps = np.finfo(float).eps
    r_bound = min(4.0 * eps * max(np.max(np.abs(radial)), np.ptp(radial)), (radial[1] - radial[0]) / 4.0)
    z_bound = min(4.0 * eps * max(np.max(np.abs(axial)), np.ptp(axial)), (axial[1] - axial[0]) / 4.0)
    for index, (radius, height) in enumerate(query):
        ir = np.argmin(np.abs(radial - radius))
        iz = np.argmin(np.abs(axial - height))
        if abs(radial[ir] - radius) <= r_bound and abs(axial[iz] - height) <= z_bound:
            interpolated[index] = flux_nodes[iz * nr + ir]
    if not np.all(np.isfinite(interpolated)):
        raise FloatingPointError("interpolated flux is not finite")
    return interpolated.reshape(target_r.shape)


__all__ = ["get_deltapsi"]
